insert into public.sop_questions (sop, q, a, options) values
(1, 'What does the Approach Aids scan flow (FRISC) cover?', 2, '["Idents, Frequencies, Rings, standby instruments","NDB, VOR/ILS, ADF, VOR x3 and standbys","Frequencies, Rings, Idents, standby instruments and Courses","Clock, QNH, Altimeter, MFRA and flight directors"]'::jsonb),
(1, 'Who makes the “Cabin Crew seats for landing” call?', 1, '["Captain","PM, normally around 6 nm from touchdown","PF, normally around 6 nm from touchdown","Nobody"]'::jsonb),
(1, 'When is the rudder trim function checked?', 1, '["On the first flight of the day for each operating crew","On all through flights","Not required unless it is an ETOPS sector","On first flights of the day only"]'::jsonb),
(1, 'The initial welcoming PA to passengers should be made by whom, and when?', 0, '["The Captain, prior to pushback","The Pilot Flying (PF), prior to pushback","The First Officer, prior to pushback","The Pilot Monitoring (PM), prior to pushback"]'::jsonb),
(1, 'What is the rule for PAs during taxi in and taxi out?', 3, '["The Captain must make all PAs to passengers","The First Officer must make all PAs to passengers","PAs are not permitted","Only essential safety PAs are permitted; if departure is delayed the Captain may inform passengers once the parking brake is set"]'::jsonb),
(1, 'Who checks the PA system from the flight deck, and when?', 0, '["The PF during Preliminary Flight Deck Preparation","The PM during Preliminary Flight Deck Preparation","It is not required as a Ryanair procedure","The CSA"]'::jsonb),
(1, 'Who checks the engine parameters (e.g. oil quantity) before engine start?', 0, '["The PF, during Flight Deck Preparation","The PM, during Flight Deck Preparation","The Captain, during the cockpit safety inspection","Nobody, as these values are monitored by the EECs"]'::jsonb),
(1, 'What is the maximum taxi speed on the apron in dry conditions?', 1, '["10 kt","15 kt","5 kt","30 kt"]'::jsonb),
(1, 'Which pilot calls the “OM” (challenge) check first?', 1, '["PM","PF","It is an automatic EGPWS callout","Nobody, it is a silent check"]'::jsonb),
(1, 'During the descent and approach preparation, who sets the Vref and autobrake?', 0, '["The PF, having handed control to the PM, sets Vref and the autobrake","The PM sets Vref and the autobrake","The Captain sets them before the approach brief (DALTA)","The FO sets them during DALTA"]'::jsonb),
(1, 'Which statement about visual approaches is correct?', 3, '["They must be fully stabilised by 1,000 ft AAL","They must be flown by the Captain only","They must be flown manually","They are treated as non-precision approaches, so a double briefing and the ten-mile rule (Flaps 1) both apply"]'::jsonb),
(1, 'What is the correct “Outer Marker” call on approach?', 1, '["“Outer Marker, XXXX feet, No Flags” (PM challenge), “Altitude Checks, No Flags” (PF response)","“Outer Marker, XXXX feet, No Flags” (PF challenge), “Altitude Checks, No Flags” (PM response)","“Outer Marker, XXXX feet, No Flags” (PF challenge), “Check, No Flags” (PM response)","“Outer Marker, XXXX feet, No Flags” (PM challenge), “Outer Marker Checks, No Flags” (PF response)"]'::jsonb),
(1, 'What is the circuit-breaker panel behind the Captain’s seat called?', 0, '["The P-18 panel","The P-12 panel","The P-6 panel","The P-3 panel"]'::jsonb),
(1, 'Where are the Ryanair non-normal flight patterns and manoeuvres found?', 0, '["The Manoeuvres section of the QRH","The Unannunciated Checklist section (Section 0) of the QRH","Operations Manual Part A","FCOM Vol 2"]'::jsonb),
(1, 'What is required of the V1 aural call on takeoff?', 0, '["It must be complete by V1","It must be commenced at V1","It must be answered by the PF with a “Check” call","It must be made by the PF"]'::jsonb),
(1, 'Which heading should be set on the MCP for takeoff?', 2, '["The expected heading allowing for drift","The first heading expected on the SID","Runway heading","It does not matter if LNAV will be used"]'::jsonb),
(1, 'On a single-channel or manual approach, what should the PM call?', 1, '["“LAND” only at the aural “MINIMUMS” call","The visual cues as they become apparent during the approach","The visual cues only at the aural “MINIMUMS” call","“GO AROUND” if not visual passing the landing gate"]'::jsonb),
(1, 'If a TCAS RA conflicts with an ATC instruction, which does the PF follow?', 0, '["TCAS","ATC","Maintain visual separation","Either TCAS or ATC"]'::jsonb),
(1, 'What cool-down period do Ryanair and CFM recommend for engine hot-section thermal stabilisation?', 1, '["One minute","Three minutes","Two minutes","30 seconds"]'::jsonb),
(1, 'With the engine shut down and chocks in place, what does normal procedure require?', 0, '["Release the parking brake, provided company procedures are followed","After heavy braking, release the parking brake for 5–6 seconds then reset","Release the parking brake on stand even without chocks","Do not set the parking brake until the brakes have been checked"]'::jsonb),
(1, 'When using the speedbrake in flight, which pilot selects it?', 2, '["The Captain, who holds the handle until it is no longer required","The PM, but the PF stows it when no longer needed","The PF, who also stows it","The FO, who holds the handle until it is no longer required"]'::jsonb),
(1, 'What is the standard FMC cost index?', 2, '["30","6","As per the flight plan","35"]'::jsonb),
(1, 'APU operation is required on the ground with the buses on AC power. What is needed?', 1, '["No fuel pump, as it will suction feed from the main tank","An AC fuel pump on the left side of the fuel manifold should be ON","All six fuel pumps should be ON","An AC fuel pump on the right side of the fuel manifold should be ON"]'::jsonb),
(1, 'The runway is wet for departure. Which statement is most correct?', 2, '["A de-rated takeoff is not allowed","Assumed thrust reduction is not allowed","Both de-rate and assumed thrust reduction are allowed","Neither de-rate nor assumed thrust reduction is allowed"]'::jsonb),
(1, 'When should the logo lights be ON?', 0, '["At night below FL100","At night","During ground operations only","Never"]'::jsonb),
(1, 'When are the emergency exit lights armed?', 2, '["During the rainbow scan","As part of the Cockpit Procedure – Captain","As part of the Preliminary Flight Deck Procedure – PF","As part of the Preliminary Flight Deck Procedure – PM"]'::jsonb),
(1, 'What is the pre-flight instrument scan?', 1, '["Time, Speed, Alt, QNH, HDG, VSI and Flags","Time, QNH, Alt, MFRA, flight directors and standby instruments","Time, FMA, V2, MFRA, VSI, HDG, Flags and standby instruments","Time, Alt, QNH, HDG and Flags"]'::jsonb),
(1, 'What must the departure taxi briefing always include?', 0, '["A review of the expected taxi routing to the departure runway","A review of the expected taxi routing at destination","A review of the passenger evacuation drill","A review of the go-around procedure"]'::jsonb),
(1, 'When should the navigation lights be ON?', 2, '["Only during darkness","From 30 min before sunset to 30 min after sunrise","Whenever AC power is connected to the aircraft buses","Before crossing an active runway, then turned off"]'::jsonb),
(1, 'What is Ryanair’s policy on maximum assumed-temperature-reduction takeoff thrust?', 1, '["Use it except when there is an emergency turn for the runway","Use it wherever permitted by the OPT or SOPs","Use it only when necessary for noise-abatement profiles","Always use it"]'::jsonb),
(1, 'On the ground, before switching on the A-system hydraulic pumps, you must ensure what?', 0, '["Personnel are clear of the tow bar, or the bypass pin is installed","Personnel are clear of the tow bar and the bypass pin is installed","The A system is never pressurised if a pushback is required","Nothing needs to be checked before switching the A pumps ON"]'::jsonb),
(1, 'If an autoland proceeds normally after 50 ft, what does the F/O (RHS) call?', 0, '["Nothing until the speedbrake deploys","“FLARE”","“RETARD”","“TOUCHDOWN”"]'::jsonb),
(1, 'What is the minimum oil quantity for dispatch?', 2, '["14 L","13 L","12 L","15 L"]'::jsonb),
(1, 'Which statement about the emergency escape rope is correct?', 2, '["It should be checked for your station only","It is present; there is no need to check it is actually attached to the flight deck","Both emergency escape ropes are attached to the flight deck","There is no requirement to check it"]'::jsonb),
(1, 'In normal operations, what does the PF call after hearing “Flaps Up, No Lights”?', 2, '["“Level Change, MCT”","“Command A”","“After Takeoff checklist”","“Level Change”"]'::jsonb),
(1, 'When does the Enhanced GPWS give an automatic “500 ft” aural call?', 1, '["At 500 ft radio altitude on all approaches","At 500 ft radio altitude on an approach with NO glideslope","At 500 ft radio altitude only on an approach with a glideslope","At 500 ft pressure altitude on all approaches"]'::jsonb),
(1, 'Who carries out a full GPWS test, and when?', 2, '["The engineers, daily","The PF, first flight or crew change only","The F/O, first flight or crew change only","The Captain, first flight or crew change only"]'::jsonb),
(1, 'Should the PF check the landing-gear lights on the aft overhead panel during pre-flight?', 1, '["No","Yes","Not if the forward-panel lights are working","There are no landing-gear lights on the aft overhead panel"]'::jsonb),
(1, 'Before the first flight, who checks the ship’s library?', 0, '["The PF","The PM","The engineer","The Captain"]'::jsonb),
(1, 'What is the correct manoeuvre for a TCAS RA?', 0, '["If manoeuvring is required, disengage autopilot and autothrottle and follow the manoeuvre shown on the PFD","If manoeuvring is required, disengage the autopilot only and follow the PFD","Use the MCP as needed with autopilot and autothrottle engaged to establish the path","If manoeuvring is required, disengage autopilot and autothrottle and fly inside the red area on the PFD"]'::jsonb),
(1, 'Is self-manoeuvring at night below the MSA permitted?', 0, '["It is prohibited","It is allowed once the landing lights are operational","It is allowed only if fully stabilised at 1,000 ft AAL","It is allowed only if fully stabilised at 500 ft AAL"]'::jsonb),
(1, 'At engine start, when does the PF call “Monitor Number ___”?', 2, '["As the start switch moves to OFF","As the engine cuts back","After the Start Valve Open light extinguishes and the PM calls “Starter cut-out”","Once N2 passes 46%"]'::jsonb),
(1, 'Must the TCAS OFF flag always be called as part of the instrument cross-check?', 3, '["True, called by the PM","It is normally indicating at this point","True, called by the PF","False"]'::jsonb),
(1, 'On a go-around, what is the correct roll mode at 400 ft if routing is available?', 2, '["VNAV","HDG","LNAV","No selection is required once TOGA is pressed"]'::jsonb),
(1, 'On the takeoff roll, after checking N1 against target and the engine indications, what does the PM call?', 1, '["Nothing","“Takeoff thrust set, indications normal”","“Indications normal”","“Throttle Hold”"]'::jsonb),
(1, 'When is the intermittent warning horn (takeoff configuration) checked?', 1, '["During pre-flight for the first flight only, by the Captain","During pre-flight for all flights, as part of the speedbrake check, by the PF","During pre-flight for all flights, as part of the speedbrake check, by the Captain only"]'::jsonb),
(1, 'How long should the APU run before it is used as a bleed source?', 1, '["1.5 min","1 min","It does not matter","3 min"]'::jsonb),
(1, 'What is the normal landing flap setting on the 737?', 1, '["15","30 and 40","25 and 40","There is no policy for this"]'::jsonb),
(1, 'What is the correct call after thrust-reverser deployment on landing with both indications green?', 1, '["Nothing is called","“Reversers Normal”","“Reversers Abnormal”","“Two Reversers Active”"]'::jsonb),
(1, 'For performance, a runway covered by more than 3 mm of slush is considered:', 0, '["A contaminated runway","A slippery runway","A wet runway","A damp runway"]'::jsonb),
(1, 'What must the PM silently verify climbing through FL200, 300 and 400?', 1, '["Pilot incapacitation","That pressurisation is normal","The recall press","Fuel and time versus the OFP"]'::jsonb),
(1, 'On two engines, continuous descent approaches are standard on:', 2, '["All approaches","ILS approaches only","All approaches except V/S NPA and SRAs","Non-precision approaches only"]'::jsonb),
(1, 'If a normal bleeds-on takeoff is planned:', 1, '["It should be mentioned in the takeoff brief","It need not be mentioned in the takeoff brief","It need only be mentioned on the first flight of the day","It should be written on the OFP"]'::jsonb),
(1, 'How must an emergency turn (engine failure on takeoff) be flown?', 2, '["At V2 (magenta bug) and 15° bank; the turn must always be complete before level acceleration and flap retraction","At V2+15 kt (white bug) and 30° bank; the turn must be complete before level acceleration and flap retraction","At V2 (magenta bug) and 15° bank; the turn need not be complete before level acceleration unless specified in the ETP","At V2 (magenta bug) and 30° bank; the turn must be complete before level acceleration and flap retraction"]'::jsonb),
(1, 'What is the landing gate for an IMC approach (precision or non-precision)?', 1, '["500 ft","1000 ft","The FAF","5 nm"]'::jsonb),
(1, 'On a NADP 1 departure with a 2500 ft QNH level-off on the SID, when may you accelerate?', 3, '["At “ALT ACQ”","At “ALT HOLD” only","1000 ft prior to level-off","Only once cleared to climb above 3000 ft AGL"]'::jsonb),
(1, 'Who briefs the reject items during the initial emergency briefing pre-flight?', 0, '["The Captain","The F/O","The PF","The PM"]'::jsonb),
(1, 'When must the cabin crew be advised of refuelling?', 1, '["Only when passengers are embarking","When passengers are embarking, disembarking or on board","Only when passengers are embarking or disembarking","There is no requirement to advise the cabin crew"]'::jsonb),
(1, 'With halogen bulbs fitted, the fixed landing lights are set ON entering the runway. When are the retractable lights turned ON?', 2, '["When cleared for takeoff","They are only used for bird avoidance","Also when entering the runway","When the cabin is secure for takeoff"]'::jsonb),
(1, 'How is the IFE switch on the overhead panel normally left?', 2, '["OFF, as it is not connected to any system","OFF, as long as galley power is not required","ON; it is always turned ON as part of the pre-flight procedure","ON in flight and OFF on the ground"]'::jsonb),
(1, 'Who completes the light test during pre-flight?', 0, '["The PF","The PM","The engineer","The Captain"]'::jsonb),
(1, 'Which items does the Captain review under “Takeoff Briefing” on the Before Takeoff checklist?', 1, '["Bleeds, speeds and SID","Packs, bleeds, speeds, SID (including initial turn), stop altitude, ET if required and adverse weather","Flaps, trim, speeds, SID initial altitude, stop altitude, emergency turn and adverse weather","The departure SID only"]'::jsonb),
(1, 'When cleared to an altitude on approach with no delay expected, what is the standard call?', 0, '["“QNH ___, passing XXX descending XXX, (No) flags, standby altimeter set”","“QNH, ALT, VSI, HDG, SPD”","“QNH ___ set, once, twice, three times, (No) flags, standby altimeter set”","“Set QNH ___, passing XXX, standby altimeter set”"]'::jsonb),
(1, 'On a V/S NPA, where are landing gear down and Flap 15 selected?', 3, '["IMC: 6 nm prior to the RWxx point","VMC: 6 nm prior to the RWxx point","VMC: 4 nm prior to the RWxx point","5 nm prior to the RWxx point"]'::jsonb),
(1, 'On a CAT I ILS with a 600 ft cloud base and 2000 m visibility, what is the latest point to select gear down?', 2, '["4 nm, but no later than 3.5 nm","6 nm","5 nm","The FAF"]'::jsonb),
(1, 'On a two-engine missed approach, what is the earliest point to start flap retraction from 15 to 5?', 0, '["400 ft","800 ft","1000 ft","1500 ft"]'::jsonb),
(1, 'How is the “FLT ALT” selector on the pressurisation panel set?', 2, '["To whatever you think is a good level","To the level closest to the FMC optimum","To the filed level, or lower if performance-limited or ATC level-capped","To the level that gives the highest TAS"]'::jsonb),
(1, 'Which callout is correct for a CAT II/IIIA autoland?', 2, '["Captain: “Passing ___ feet, flare armed”","F/O: “___ radio, flare armed”","F/O: “Passing ___ radio, flare armed”","Captain: “Passing ___ radio”"]'::jsonb),
(1, 'When should the PF “bug up” on a normal NADP2 departure?', 2, '["At MFRA","At 3000 ft AGL or ALT ACQ, whichever is later","At 1,000 ft AAL","At 3000 ft AGL or ALT ACQ, whichever is earlier"]'::jsonb),
(1, 'May crews plan to fly high speed below FL100?', 2, '["Yes, to improve fuel burn","Only if running behind schedule","Only in the climb, in Class A/B/C airspace, if authorised by ATC","Never"]'::jsonb),
(1, 'What is the correct FMC sequence when briefing a SID?', 0, '["RTE pages 1 and 2, INIT/REF, LEGS","INIT/REF, RTE pages 1 and 2, LEGS","RTE pages 1 and 2 only","None of the above"]'::jsonb),
(1, 'You find a missing security seal during your walk-around. What do you do?', 0, '["Contact Maintrol or an on-duty engineer to replace the seal","Replace the seal on the commander’s authority","There is no requirement to have a security seal on the aircraft","Obtain a new security seal from the crew room"]'::jsonb),
(1, 'The landing gate for a circling approach is 300 ft AAL. What must be established by 500 ft AAL?', 2, '["Vertical path and landing configuration","Lateral path and landing configuration","Landing configuration only","Nothing, since the landing gate is 300 ft AAL"]'::jsonb),
(1, 'Which “ENGINE START IGN” selection is made for engine start?', 2, '["Right for the first start at a Ryanair base, then alternate","Both, for all flights","Right when operating through a manned maintenance base","Left when operating through a manned maintenance base"]'::jsonb),
(1, 'What is the earliest point the autopilot may be engaged on a NADP2 departure?', 2, '["158 ft minimum use height","800 ft, as the thrust mode annunciates ARM","1,000 ft AAL","After the “Flaps Up, No Lt” call"]'::jsonb),
(1, 'Are night-time circle-to-land manoeuvres permitted?', 1, '["They are prohibited","They are permitted if a visual or electronic slope indicator is operational on the landing runway","They are not subject to a double briefing","They are not subject to the ten-mile rule (Flaps 1)"]'::jsonb),
(1, 'What altitude is set on the MCP before ATC clearance is received?', 1, '["Expected SID minus 100 ft","Expected SID plus 100 ft","Expected SID clearance limit","Expected SID plus 1100 ft"]'::jsonb),
(1, 'What is the standard V1 callout when taking off on a wet runway?', 2, '["“WET V1”","“Continue”","“V1”","“V1 Wet”"]'::jsonb),
(1, 'What is the first step when starting the engines?', 0, '["Announce the engine-start sequence; plan to start engines for minimum fuel consumption","There is no requirement to announce the engine-start sequence","Start engines as quickly as possible to minimise pushback time","Start engines only after pushback is complete"]'::jsonb),
(1, 'Runway conditions permitting, how is the autobrake set?', 0, '["As determined by the crew using the QRH (PI section) or the OPT","Three (3)","One (1)","Two (2)"]'::jsonb),
(1, 'What position should the isolation valve be in for engine start?', 0, '["OPEN","AUTO","CLOSE","ISOLATE"]'::jsonb),
(1, 'Which is the mandatory climb mode after all MCP altitude / flight-level changes?', 1, '["Level Change (MCP SPD)","VNAV","Vertical Speed (V/S)","There is no default mode"]'::jsonb),
(1, 'What must the flight crew give the CSS (Cabin Services Supervisor) before departure?', 0, '["One copy of the SEP manual plus the CCIs (Cabin Crew Instructions)","The SEP manual only, no need for the CCIs","The CCIs only, but not the SEP manual","Neither the SEP manual nor the CCIs anymore"]'::jsonb),
(1, 'During taxi in and taxi out, how are taxi instructions handled?', 3, '["The Captain writes them in the FMC scratchpad and monitors progress against the chart","The Captain (LHS) writes down and cross-checks all taxi instructions; the F/O (RHS) monitors progress against the chart","The F/O (RHS) writes them down, the Captain cross-checks, then the Captain monitors progress against the chart","The F/O (RHS) acknowledges the instructions, writes them in the FMC scratchpad, and ensures both pilots understand them"]'::jsonb),
(1, 'When cleared to a flight level, what is the standard callout and by whom?', 1, '["PM: “Set STD, passing XXX”","PF: “Set STD, passing XXX, climbing XXX”","PF: “Set STD”, and PM calls “passing XXX for XXX”","PM: “Set STD”"]'::jsonb),
(1, 'May the electric hydraulic pumps be switched ON while refuelling is in progress?', 0, '["Yes","No","Sometimes","Only when the bypass pin is installed"]'::jsonb),
(1, 'What does the F/O call prior to taxi?', 1, '["“Ground equipment clear right”","“Clear right”","“Clear”","Nothing"]'::jsonb),
(1, 'The landing gate requires you to be fully stabilised how?', 3, '["With all checklists complete at 1,000 ft (all approaches)","With all checklists complete at 500 ft (all approaches)","With all checklists complete at 1,000 ft except landing lights (VMC)","With all checklists complete at 1,000 ft except landing lights (IMC)"]'::jsonb),
(1, 'What is the 500 ft call on an ILS approach?', 2, '["“Five hundred feet” (PF), “Check, passing XXXX” (PM)","“Five hundred feet” (PM), “Passing 500, Check” (PF)","“Five hundred, continue / go-around” (PM), “Check” (PF)","“Five hundred, continue / go-around” (PF), “Check” (PM)"]'::jsonb),
(1, 'Who checks the “Takeoff CONFIG” warning, and when?', 0, '["The PF during the Preliminary Flight Deck Procedure","The PM during the Preliminary Flight Deck Procedure","The Captain only","The First Officer only"]'::jsonb),
(1, 'Which statement about low-drag non-precision approaches is correct?', 0, '["They are not normally applicable to a V/S NPA","They are not permitted at night","They are permitted in Class A/B/C/D airspace only","They are not permitted with a continuous descent approach (CDA)"]'::jsonb),
(1, 'At engine start, when are the start levers moved to idle detent?', 1, '["When N2 reaches 25% (only requirement)","When N1 rotation is observed and N2 reaches 25%","When N2 reaches 20% (only requirement)","When N1 rotation is observed and N2 reaches 20%"]'::jsonb),
(1, 'Before the first flight, who first checks the maintenance status?', 2, '["The PM","The Captain","The PF","The First Officer"]'::jsonb),
(1, 'What is the standard call for a passenger evacuation?', 3, '["“This is your Captain speaking, evacuate the aircraft using all available exits”, repeated once","“This is your Captain speaking, evacuate the aircraft using right/left emergency exits only”, repeated once","“This is an emergency. Evacuate the aircraft using right/left emergency exits only”, repeated once","“This is an emergency. Evacuate the aircraft using all available exits”, repeated once"]'::jsonb),
(1, 'What is the earliest height that standard (1013 hPa) may be set on climb-out?', 2, '["As soon as cleared to a flight level by ATC","Passing the transition altitude","Above 3000 ft AAL and when cleared to a flight level","When passing 3000 ft on the altimeter"]'::jsonb),
(1, 'The PF completes the Before Taxi scan and blanks the lower display by pushing the MFD. Is this correct?', 2, '["No, all engine parameters must be monitored for takeoff and flight","No, engine parameters will not be visible for the takeoff roll, making an exceedance impossible to spot","Yes, the pop-up feature reveals the lower display on an exceedance or engine failure","Yes, it always brings up the compact engine display on the upper DU"]'::jsonb),
(1, 'Which is correct for the emergency turn procedure (ETP1)?', 0, '["After the turn is complete and at or above MFRA, the PF calls “Bug up”, accelerates, retracts flaps, then selects Level Change and MCT","Once at MSA, the PF calls “Bug up” and accelerates through flap retraction, then selects Level Change MCT","Once at flap-retraction height, the PF calls “Bug up” and accelerates through flap retraction, then selects Level Change MCT","After 1000 ft AGL the PF calls “Bug up” and retracts flaps on schedule, then selects LVL CHG and MCT"]'::jsonb),
(1, 'Turbulence is encountered and the Captain decides to switch on the seatbelt signs. Who actually moves the sign from AUTO to ON?', 2, '["The Captain","The PF, as his area of responsibility in flight","The PM, as his area of responsibility in flight","The First Officer"]'::jsonb),
(1, 'On an engine failure at takeoff, you should:', 2, '["Follow the SID","Always climb straight ahead","Climb straight ahead unless there is an emergency turn, and inform ATC","Follow the SID unless there is an emergency turn"]'::jsonb);
